import { supabase } from '@/lib/supabase'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'
export const fetchCache = 'force-no-store'

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const status = searchParams.get('status') ?? 'available'

  const { data: produce, error } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('status', status)
    .order('created_at', { ascending: false })

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!produce?.length) return NextResponse.json([])

  const farmerIds = [...new Set(produce.map((p) => p.farmer_id))]

  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, village, slug, phone, method, region_slug, pickup_locations')
    .in('id', farmerIds)
    .eq('active', true)

  const farmerMap = Object.fromEntries((farmers ?? []).map((f) => [f.id, f]))

  const result = produce
    .map((p) => ({ ...p, farmer: farmerMap[p.farmer_id] ?? null }))
    .filter((p) => p.farmer !== null)

  return NextResponse.json(result)
}
import { supabase } from '@/lib/supabase'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'
export const fetchCache = 'force-no-store'

const CATEGORY_KEYWORDS: Record<string, string[]> = {
  vegetables: [
    'tomato', 'capsicum', 'brinjal', 'eggplant', 'bean', 'pea', 'pumpkin',
    'gourd', 'onion', 'potato', 'garlic', 'carrot', 'radish', 'cucumber',
    'okra', 'ladyfinger', 'drumstick', 'ridge gourd', 'bottle gourd', 'chilli',
    'pepper', 'bitter gourd', 'cluster bean', 'snake gourd',
  ],
  fruits: [
    'mango', 'banana', 'papaya', 'guava', 'pomegranate', 'orange', 'lime',
    'lemon', 'coconut', 'tamarind', 'jackfruit', 'sapota', 'fig', 'grapes',
    'watermelon', 'muskmelon', 'pineapple', 'custard apple',
  ],
  grains: [
    'rice', 'wheat', 'jowar', 'bajra', 'ragi', 'maize', 'corn', 'dal',
    'lentil', 'chickpea', 'groundnut', 'sesame', 'turmeric', 'ginger',
    'pulses', 'toor', 'moong', 'urad', 'chana',
  ],
  leafy: [
    'spinach', 'methi', 'fenugreek', 'coriander', 'mint', 'curry',
    'amaranth', 'sorrel', 'moringa', 'drumstick leaves', 'palak',
  ],
}

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url)
  const q = searchParams.get('q') ?? ''
  const method = searchParams.get('method') ?? ''
  const category = searchParams.get('category') ?? ''

  const { data: produce } = await supabase
    .from('produce_listings')
    .select('*')
    .eq('status', 'available')
    .order('created_at', { ascending: false })

  let filtered = produce ?? []

  if (q) {
    const query = q.toLowerCase()
    filtered = filtered.filter(
      (p) =>
        p.name?.toLowerCase().includes(query) ||
        p.variety?.toLowerCase().includes(query) ||
        p.description?.toLowerCase().includes(query)
    )
  }

  if (method && method !== 'all') {
    filtered = filtered.filter((p) =>
      p.method?.toLowerCase().includes(method.toLowerCase())
    )
  }

  if (category && category !== 'all' && CATEGORY_KEYWORDS[category]) {
    const keywords = CATEGORY_KEYWORDS[category]
    filtered = filtered.filter((p) =>
      keywords.some((kw) => p.name?.toLowerCase().includes(kw))
    )
  }

  if (!filtered.length) return NextResponse.json([])

  const farmerIds = [...new Set(filtered.map((p) => p.farmer_id))]

  const { data: farmers } = await supabase
    .from('farmers')
    .select('id, name, village, slug, phone, method, pickup_locations')
    .in('id', farmerIds)
    .eq('active', true)

  const farmerMap = Object.fromEntries((farmers ?? []).map((f) => [f.id, f]))

  const result = filtered
    .map((p) => ({ ...p, farmer: farmerMap[p.farmer_id] ?? null }))
    .filter((p) => p.farmer !== null)

  return NextResponse.json(result)
}
import { NextRequest, NextResponse } from 'next/server'
import { createClient } from '@supabase/supabase-js'

export async function POST(req: NextRequest) {
  try {
    const body = await req.json()
    const { farmer_id, reviewer_name, star_rating, review_text, produce_ordered } = body

    if (!farmer_id || !reviewer_name?.trim() || !star_rating) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 })
    }
    if (star_rating < 1 || star_rating > 5) {
      return NextResponse.json({ error: 'Invalid rating' }, { status: 400 })
    }

    const supabase = createClient(
      process.env.NEXT_PUBLIC_SUPABASE_URL!,
      process.env.SUPABASE_SERVICE_ROLE_KEY ?? process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
    )

    const { data: review, error } = await supabase
      .from('reviews')
      .insert({
        farmer_id,
        reviewer_name: reviewer_name.trim(),
        star_rating,
        review_text: review_text?.trim() || null,
        produce_ordered: produce_ordered?.trim() || null,
        approved: true,
      })
      .select('*')
      .single()

    if (error) return NextResponse.json({ error: error.message }, { status: 500 })

    // Recalculate rating_avg and buyer_count from all approved reviews
    const { data: allReviews } = await supabase
      .from('reviews')
      .select('star_rating')
      .eq('farmer_id', farmer_id)
      .eq('approved', true)

    if (allReviews && allReviews.length > 0) {
      const avg =
        allReviews.reduce((sum: number, r: { star_rating: number }) => sum + r.star_rating, 0) /
        allReviews.length
      await supabase
        .from('farmers')
        .update({
          rating_avg: Math.round(avg * 10) / 10,
          buyer_count: allReviews.length,
        })
        .eq('id', farmer_id)
    }

    return NextResponse.json({ review })
  } catch {
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}
import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'

export async function POST(request: NextRequest) {
  // Create admin client inside handler so missing env var doesn't crash the build
  const supabaseAdmin = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const body = await request.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid request' }, { status: 400 })

  const { listingId, farmerId, payload } = body

  if (!listingId || !farmerId || !payload) {
    return NextResponse.json({ error: 'Missing fields' }, { status: 400 })
  }

  // Verify this listing belongs to the farmer before updating
  const { data: existing } = await supabaseAdmin
    .from('produce_listings')
    .select('id')
    .eq('id', listingId)
    .eq('farmer_id', farmerId)
    .maybeSingle()

  if (!existing) {
    return NextResponse.json({ error: 'Listing not found or access denied' }, { status: 403 })
  }

  const { data: updated, error } = await supabaseAdmin
    .from('produce_listings')
    .update(payload)
    .eq('id', listingId)
    .select('id')

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  if (!updated?.length) return NextResponse.json({ error: 'Update failed — no rows changed' }, { status: 500 })

  return NextResponse.json({ ok: true })
}

