'use client'

import { useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import LanguageToggle from '@/components/LanguageToggle'
import { useLang } from '@/lib/LanguageContext'

type Step = 'phone' | 'otp'

export default function FarmerLoginPage() {
  const router = useRouter()
  const { tx } = useLang()
  const [step, setStep]     = useState<Step>('phone')
  const [phone, setPhone]   = useState('')
  const [otp, setOtp]       = useState('')
  const [loading, setLoading] = useState(false)
  const [error, setError]   = useState('')

  const digits = phone.replace(/\D/g, '').slice(-10)
  const canSend = digits.length === 10

  const handleSendOtp = async () => {
    if (!canSend) return
    setLoading(true)
    setError('')

    const res = await fetch('/api/auth/send-otp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: digits }),
    })
    const json = await res.json().catch(() => ({}))
    setLoading(false)

    if (!res.ok) {
      setError(json.error ?? 'Could not send OTP. Please try again.')
      return
    }
    setOtp('')
    setStep('otp')
  }

  const handleVerify = async () => {
    if (!otp.trim()) return
    setLoading(true)
    setError('')

    const res = await fetch('/api/auth/verify-otp', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ phone: digits, otp: otp.trim() }),
    })
    const json = await res.json().catch(() => ({}))
    setLoading(false)

    if (!res.ok) {
      setError(json.error ?? tx.otpInvalid)
      return
    }

    localStorage.setItem('yff_farmer_id', json.farmerId)
    localStorage.setItem('yff_farmer_slug', json.farmerSlug)
    router.replace('/farmer/dashboard')
  }

  return (
    <main className="min-h-screen bg-gray-50 flex flex-col items-center justify-center px-4">
      <div className="absolute top-4 right-4">
        <LanguageToggle />
      </div>

      <div className="w-full max-w-sm">
        {/* Logo */}
        <div className="text-center mb-8">
          <Link href="/consumer" className="inline-flex flex-col items-center">
            <div className="w-16 h-16 bg-green-700 rounded-2xl flex items-center justify-center mb-3">
              <span className="text-white font-black text-lg">YFF</span>
            </div>
          </Link>
          <h1 className="text-2xl font-extrabold text-gray-900">
            Farmer Login / రైతు లాగిన్
          </h1>
          <p className="text-gray-500 text-sm mt-1">
            {step === 'phone'
              ? 'Sign in with WhatsApp / వాట్సాప్ తో సైన్ ఇన్'
              : tx.otpSentMsg.replace('{phone}', digits)}
          </p>
        </div>

        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 space-y-4">
          {/* ── Step 1: Phone number ── */}
          {step === 'phone' && (
            <>
              <div>
                <label className="text-sm font-semibold text-gray-700 block mb-2">
                  WhatsApp Number / వాట్సాప్ నంబర్
                </label>
                <div className="flex gap-2">
                  <span className="flex items-center px-3 bg-gray-50 border border-gray-200 rounded-xl text-sm text-gray-600 font-medium whitespace-nowrap">
                    +91
                  </span>
                  <input
                    type="tel"
                    inputMode="numeric"
                    placeholder="9876543210"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    onKeyDown={(e) => e.key === 'Enter' && handleSendOtp()}
                    className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
                    maxLength={10}
                  />
                </div>
              </div>

              {error && (
                <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
              )}

              <button
                onClick={handleSendOtp}
                disabled={loading || !canSend}
                className="w-full bg-green-700 text-white font-bold py-4 rounded-xl text-base disabled:opacity-50 active:bg-green-800 transition-colors"
              >
                {loading ? tx.sending : tx.sendOtp}
              </button>

              <p className="text-xs text-gray-500 text-center leading-snug">
                New here? Just enter your number and continue — we&apos;ll set up your profile.<br />
                కొత్తవారా? మీ నంబర్ నమోదు చేసి కొనసాగండి.
              </p>
            </>
          )}

          {/* ── Step 2: OTP entry ── */}
          {step === 'otp' && (
            <>
              <div>
                <label className="text-sm font-semibold text-gray-700 block mb-2">
                  {tx.enterOtp} / కోడ్ నమోదు చేయండి
                </label>
                <input
                  type="tel"
                  inputMode="numeric"
                  placeholder={tx.otpPlaceholder}
                  value={otp}
                  onChange={(e) => setOtp(e.target.value.replace(/\D/g, '').slice(0, 6))}
                  onKeyDown={(e) => e.key === 'Enter' && handleVerify()}
                  className="w-full border border-gray-200 rounded-xl px-4 py-3 text-base text-center tracking-widest font-bold focus:border-green-500 focus:outline-none"
                  autoFocus
                  maxLength={6}
                />
                <p className="text-xs text-gray-500 mt-1 text-center">
                  Sent to +91 {digits} · Valid 10 minutes
                </p>
              </div>

              {error && (
                <p className="text-sm text-red-600 bg-red-50 rounded-xl px-3 py-2">{error}</p>
              )}

              <button
                onClick={handleVerify}
                disabled={loading || otp.length < 6}
                className="w-full bg-green-700 text-white font-bold py-4 rounded-xl text-base disabled:opacity-50 active:bg-green-800 transition-colors"
              >
                {loading ? tx.verifying : tx.verifyOtp}
              </button>

              <div className="flex items-center justify-between text-xs">
                <button
                  onClick={() => { setStep('phone'); setOtp(''); setError('') }}
                  className="text-gray-500 underline"
                >
                  {tx.changeNumber}
                </button>
                <button
                  onClick={handleSendOtp}
                  disabled={loading}
                  className="text-green-700 font-semibold underline disabled:opacity-50"
                >
                  {tx.resendOtp}
                </button>
              </div>
            </>
          )}
        </div>

        <p className="text-center text-xs text-gray-400 mt-6">
          <Link href="/consumer" className="text-green-700 underline">
            Browse produce instead / పంట బ్రౌజ్ చేయండి
          </Link>
        </p>
      </div>
    </main>
  )
}

